"use client";

import { keepFormOnSubmit } from "@/lib/use-keep-form";
import { useActionState, useState, useTransition } from "react";
import { createBanner, createCoupon, createGalleryItem, deleteBanner, deleteCategory, deleteGalleryItem, saveCategory, saveSettings, setUserRole, toggleBanner, toggleCoupon, toggleGalleryItem, updateLead } from "@/app/admin/actions";
import { uploadFile } from "./MediaUploader";

export function CategoryForm({ parents, initial }: { parents: { id: string; name: string }[]; initial?: { id: string; name: string; description: string | null; parentId: string | null; sortOrder: number; isActive: boolean } }) {
  const [state, action, pending] = useActionState(saveCategory, undefined);
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="grid gap-2 sm:grid-cols-[1fr_1fr_160px_80px_auto_auto] sm:items-end">
      {initial && <input type="hidden" name="id" value={initial.id} />}
      <input name="name" defaultValue={initial?.name} placeholder="Category name" className="input" required aria-label="Name" />
      <input name="description" defaultValue={initial?.description ?? ""} placeholder="Short description" className="input" aria-label="Description" />
      <select name="parentId" defaultValue={initial?.parentId ?? ""} className="input" aria-label="Parent">
        <option value="">Top level</option>
        {parents.filter((p) => p.id !== initial?.id).map((p) => <option key={p.id} value={p.id}>Under {p.name}</option>)}
      </select>
      <input name="sortOrder" type="number" min={0} defaultValue={initial?.sortOrder ?? 0} className="input" aria-label="Sort order" />
      <label className="flex items-center gap-1 text-sm"><input type="checkbox" name="isActive" defaultChecked={initial?.isActive ?? true} className="accent-brass" /> Live</label>
      <button disabled={pending} className={initial ? "btn-outline" : "btn-primary"}>{initial ? "Save" : "Add"}</button>
      {state?.error && <p className="text-xs text-danger sm:col-span-6">{state.error}</p>}
    </form>
  );
}

export function DeleteCategoryButton({ id }: { id: string }) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span>
      <button disabled={pending} onClick={() => confirm("Delete this category?") && start(async () => setErr((await deleteCategory(id))?.error ?? null))} className="text-xs text-danger hover:underline">Delete</button>
      {err && <span className="ml-2 text-xs text-danger">{err}</span>}
    </span>
  );
}

const LEAD_STATUSES = ["NEW", "CONTACTED", "QUOTED", "WON", "LOST"] as const;
export function LeadStatus({ id, status, note }: { id: string; status: (typeof LEAD_STATUSES)[number]; note: string }) {
  const [pending, start] = useTransition();
  const [n, setN] = useState(note);
  return (
    <div className="space-y-1.5">
      <select disabled={pending} defaultValue={status} onChange={(e) => start(() => updateLead(id, e.target.value as (typeof LEAD_STATUSES)[number]))} className="input py-1.5 text-xs" aria-label="Lead status">
        {LEAD_STATUSES.map((s) => <option key={s} value={s}>{s.charAt(0) + s.slice(1).toLowerCase()}</option>)}
      </select>
      <input value={n} onChange={(e) => setN(e.target.value)} onBlur={() => n !== note && start(() => updateLead(id, status, n))} placeholder="Add note…" className="input py-1.5 text-xs" aria-label="Internal note" />
    </div>
  );
}

function useUpload(folder: "gallery" | "banners") {
  const [url, setUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const upload = async (f?: File) => {
    if (!f) return;
    setBusy(true);
    setErr(null);
    try {
      setUrl((await uploadFile(f, folder)).url);
    } catch (e) {
      setErr((e as Error).message);
    }
    setBusy(false);
  };
  return { url, setUrl, busy, err, upload };
}

export function GalleryUploadForm() {
  const up = useUpload("gallery");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState<"ENGRAVING" | "B2B_PROJECT" | "STORE">("ENGRAVING");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      <div className="sm:col-span-2">
        <label className="label" htmlFor="g-file">Photo or video (MP4/WebM up to 60 MB)</label>
        <input id="g-file" type="file" accept="image/*,video/mp4,video/webm" onChange={(e) => void up.upload(e.target.files?.[0])} className="text-sm" />
        {up.busy && <p className="text-xs text-muted">Uploading…</p>}
        {up.err && <p className="text-xs text-danger">{up.err}</p>}
        {up.url && <p className="text-xs text-success">Uploaded ✓</p>}
      </div>
      <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Title, e.g. 200 engraved kumkum bowls" className="input" aria-label="Title" />
      <select value={category} onChange={(e) => setCategory(e.target.value as typeof category)} className="input" aria-label="Section">
        <option value="ENGRAVING">Laser engraving</option><option value="B2B_PROJECT">B2B / commercial project</option><option value="STORE">Store</option>
      </select>
      <input value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Description (optional)" className="input sm:col-span-2" aria-label="Description" />
      <button
        disabled={pending || !up.url || title.trim().length < 2}
        onClick={() => start(async () => {
          const r = await createGalleryItem({ title, description, category, url: up.url });
          if (r?.error) setMsg(r.error);
          else { setMsg("Published to gallery."); setTitle(""); setDescription(""); up.setUrl(""); }
        })}
        className="btn-primary sm:col-span-2"
      >
        Publish to gallery
      </button>
      {msg && <p className="text-sm sm:col-span-2">{msg}</p>}
    </div>
  );
}

export function GalleryItemActions({ id, isPublished }: { id: string; isPublished: boolean }) {
  const [pending, start] = useTransition();
  return (
    <div className="flex gap-3 text-xs">
      <button disabled={pending} onClick={() => start(() => toggleGalleryItem(id, !isPublished))} className="text-maroon hover:underline">{isPublished ? "Hide" : "Publish"}</button>
      <button disabled={pending} onClick={() => confirm("Delete this item?") && start(() => deleteGalleryItem(id))} className="text-danger hover:underline">Delete</button>
    </div>
  );
}

export function BannerForm() {
  const up = useUpload("banners");
  const [f, setF] = useState({ title: "", subtitle: "", ctaLabel: "", ctaHref: "", sortOrder: 0 });
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      <div className="sm:col-span-2">
        <label className="label" htmlFor="b-file">Banner image (wide, ideally 1600×600)</label>
        <input id="b-file" type="file" accept="image/*" onChange={(e) => void up.upload(e.target.files?.[0])} className="text-sm" />
        {up.busy && <p className="text-xs text-muted">Uploading…</p>}
        {up.err && <p className="text-xs text-danger">{up.err}</p>}
        {up.url && <p className="text-xs text-success">Uploaded ✓</p>}
      </div>
      <input value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} placeholder="Headline" className="input sm:col-span-2" aria-label="Headline" />
      <input value={f.subtitle} onChange={(e) => setF({ ...f, subtitle: e.target.value })} placeholder="Sub-text" className="input sm:col-span-2" aria-label="Sub-text" />
      <input value={f.ctaLabel} onChange={(e) => setF({ ...f, ctaLabel: e.target.value })} placeholder="Button label, e.g. Shop now" className="input" aria-label="Button label" />
      <input value={f.ctaHref} onChange={(e) => setF({ ...f, ctaHref: e.target.value })} placeholder="Link, e.g. /category/brass" className="input" aria-label="Button link" />
      <button
        disabled={pending || !up.url || f.title.trim().length < 2}
        onClick={() => start(async () => {
          const r = await createBanner({ ...f, image: up.url });
          if (r?.error) setMsg(r.error);
          else { setMsg("Banner is live on the home page."); setF({ title: "", subtitle: "", ctaLabel: "", ctaHref: "", sortOrder: 0 }); up.setUrl(""); }
        })}
        className="btn-primary sm:col-span-2"
      >
        Add banner
      </button>
      {msg && <p className="text-sm sm:col-span-2">{msg}</p>}
    </div>
  );
}

export function BannerActions({ id, isActive }: { id: string; isActive: boolean }) {
  const [pending, start] = useTransition();
  return (
    <div className="flex gap-3 text-xs">
      <button disabled={pending} onClick={() => start(() => toggleBanner(id, !isActive))} className="text-maroon hover:underline">{isActive ? "Hide" : "Show"}</button>
      <button disabled={pending} onClick={() => confirm("Delete this banner?") && start(() => deleteBanner(id))} className="text-danger hover:underline">Delete</button>
    </div>
  );
}

export function CouponForm() {
  const [state, action, pending] = useActionState(createCoupon, undefined);
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="grid gap-2 sm:grid-cols-4">
      <input name="code" placeholder="CODE" className="input uppercase" required aria-label="Code" />
      <select name="type" className="input" aria-label="Type"><option value="PERCENT">% off</option><option value="FLAT">₹ off</option></select>
      <input name="value" type="number" step="0.01" min="1" placeholder="Value" className="input" required aria-label="Value" />
      <input name="minOrder" type="number" min="0" placeholder="Min order ₹" className="input" aria-label="Minimum order" />
      <input name="maxDiscount" type="number" min="0" placeholder="Max discount ₹" className="input" aria-label="Maximum discount" />
      <input name="usageLimit" type="number" min="1" placeholder="Usage limit" className="input" aria-label="Usage limit" />
      <input name="validTo" type="date" className="input" aria-label="Valid until" />
      <input name="description" placeholder="Description" className="input" aria-label="Description" />
      {state?.error && <p className="text-sm text-danger sm:col-span-4">{state.error}</p>}
      {state?.ok && <p className="text-sm text-success sm:col-span-4">Coupon created.</p>}
      <button disabled={pending} className="btn-primary sm:col-span-4">Create coupon</button>
    </form>
  );
}

export function CouponToggle({ id, isActive }: { id: string; isActive: boolean }) {
  const [pending, start] = useTransition();
  return <button disabled={pending} onClick={() => start(() => toggleCoupon(id, !isActive))} className="text-xs text-maroon hover:underline">{isActive ? "Disable" : "Enable"}</button>;
}

